import { defineStore } from 'pinia';
import { getSeoAds } from '@/services/apiTableAdmin.js';

export const useAdsTable = defineStore('useAdsTable', {
   state: () => ({
      data: null,
      itemRow: [],
      headerRows: [
         {
            name: 'ID',
            width: '50px',
            helper: false,
         },
         {
            name: 'Сорт.',
            helper: false,
            width: '50px',
         },
         {
            name: 'URL',
            helper: false,
            width: '75px',
         },
         {
            name: 'H1',
            helper: false,
            width: '100px',
         },
         {
            name: 'Title',
            helper: false,
            width: '100px',
         },
         {
            name: 'Description',
            helper: false,
            width: '100px',
         },
         {
            name: 'Keywords',
            helper: false,
            width: '100px',
         },
         {
            name: 'Noindex',
            helper: false,
            width: '50px',
         },
         {
            name: 'Город',
            helper: false,
            width: '100px',
         },
         {
            name: '',
            helper: false,
            width: '75px',
         },
      ],
      pagination: { currentPage: 0, perPage: 0, totalPages: 0 },
   }),

   actions: {
      async getSeoAdsItem(params) {
         const data = await getSeoAds(params);
         this.pagination.currentPage = data?.current_page;
         this.pagination.perPage = data?.total_count;
         this.pagination.totalPages = data?.total_page;
         this.data = data;
         this.itemRow = data?.data.map((item) => ({
            id: {
               value: item?.id,
               type: 'text',
               contenteditable: false,
            },
            date: {
               value: item?.sort,
               type: 'text',
               contenteditable: false,
            },
            url: {
               value: item?.url.url,
               type: 'link',
               contenteditable: false,
            },
            h1: {
               value: item?.h1,
               type: 'text',
               contenteditable: false,
            },
            title: {
               value: item?.title,
               type: 'text',
               contenteditable: false,
            },
            description: {
               value: item?.description,
               type: 'text',
               contenteditable: false,
            },
            keywords: {
               value: item?.keywords,
               type: 'text',
               contenteditable: false,
            },
            Noindex: {
               value: item?.is_no_index ? 'есть' : 'нет',
               type: 'text',
               contenteditable: false,
            },
            city: {
               value: item?.city?.title,
               type: 'text',
               contenteditable: false,
            },
            option: { slot: 'end', contenteditable: false, id: 1 },
         }));
      },

      //  siteMapInfoErrorFetch(){
      //  }
   },

   getters: {
      getHeaderRow: (state) => state.headerRows,
      getItemRow: (state) => state.itemRow,
      getPagination: (state) => state.pagination,
   },
});
